/* 轻量 PIXI 兼容层：仅暴露 Application / Container / Sprite / Graphics / Texture
 * 后端使用 canvas 2D 渲染，避免引入 ~600KB 的 PIXI 库。
 * 对于「天依物语」的场景（背景、人物立绘、简单粒子）已经足够。
 */
(function (global) {
    'use strict';

    class Container {
        constructor() {
            this.children = [];
            this.x = 0; this.y = 0;
            this.scaleX = 1; this.scaleY = 1;
            this.rotation = 0;
            this.alpha = 1;
            this.visible = true;
            this.width = 0; this.height = 0;
        }
        addChild(child) { this.children.push(child); return child; }
        removeChild(child) {
            const i = this.children.indexOf(child);
            if (i >= 0) this.children.splice(i, 1);
        }
        removeChildren() { this.children = []; }
        destroy() { this.children = []; }
    }

    class Texture {
        constructor(source) {
            this.source = source;
            this.width = 0; this.height = 0;
            if (source) this._resolveSize();
        }
        _resolveSize() {
            if (typeof Image !== 'undefined' && this.source instanceof Image) {
                this.width = this.source.naturalWidth || this.source.width || 0;
                this.height = this.source.naturalHeight || this.source.height || 0;
            } else if (this.source && this.source.width) {
                this.width = this.source.width;
                this.height = this.source.height;
            }
        }
        static from(url) {
            return new Promise((resolve, reject) => {
                const img = new Image();
                img.onload = () => resolve(new Texture(img));
                img.onerror = reject;
                img.src = url;
            });
        }
    }

    class Sprite extends Container {
        constructor(texture) {
            super();
            this.texture = texture || new Texture(null);
            this.width = this.texture.width;
            this.height = this.texture.height;
            this.anchorX = 0; this.anchorY = 0;
        }
        setTexture(texture) {
            this.texture = texture;
            this.width = texture.width;
            this.height = texture.height;
        }
    }

    class Graphics extends Container {
        constructor() {
            super();
            this.commands = [];
            this.lineWidth = 1;
            this.strokeStyle = '#000';
            this.fillStyle = '#000';
            this.lineAlpha = 1;
        }
        clear() { this.commands = []; return this; }
        beginFill(color, alpha) { this.commands.push({ op: 'fill', color, alpha: alpha || 1 }); return this; }
        lineStyle(width, color, alpha) { this.lineWidth = width; this.strokeStyle = color; this.lineAlpha = alpha || 1; return this; }
        moveTo(x, y) { this.commands.push({ op: 'move', x, y }); return this; }
        lineTo(x, y) { this.commands.push({ op: 'line', x, y }); return this; }
        closePath() { this.commands.push({ op: 'close' }); return this; }
        drawCircle(x, y, r) { this.commands.push({ op: 'circle', x, y, r }); return this; }
        drawRect(x, y, w, h) { this.commands.push({ op: 'rect', x, y, w, h }); return this; }
        drawRoundedRect(x, y, w, h, r) { this.commands.push({ op: 'roundRect', x, y, w, h, r }); return this; }
    }

    class Application {
        constructor(opts = {}) {
            this.width = opts.width || 800;
            this.height = opts.height || 600;
            this.backgroundColor = opts.backgroundColor || 0x000000;
            this.view = document.createElement('canvas');
            this.view.width = this.width;
            this.view.height = this.height;
            this.view.style.display = 'block';
            this.view.style.width = '100%';
            this.view.style.height = '100%';
            this.stage = new Container();
            this.ticker = { add: () => {}, remove: () => {} };
            this.renderer = { render: () => {} };
            this._destroyed = false;
        }
        async init() {
            this.ctx = this.view.getContext('2d');
            this._raf();
            return this;
        }
        _raf() {
            if (this._destroyed) return;
            this._draw();
            requestAnimationFrame(() => this._raf());
        }
        _draw() {
            const ctx = this.ctx;
            if (!ctx) return;
            ctx.save();
            ctx.fillStyle = '#' + this.backgroundColor.toString(16).padStart(6, '0');
            ctx.fillRect(0, 0, this.view.width, this.view.height);
            ctx.clearRect(0, 0, this.view.width, this.view.height);
            this._renderContainer(this.stage, ctx, 0, 0);
            ctx.restore();
        }
        _renderContainer(c, ctx, ox, oy) {
            if (!c.visible) return;
            ctx.save();
            ctx.globalAlpha = (ctx.globalAlpha || 1) * c.alpha;
            const x = ox + c.x;
            const y = oy + c.y;
            ctx.translate(x, y);
            ctx.rotate(c.rotation);
            ctx.scale(c.scaleX, c.scaleY);
            if (c instanceof Sprite && c.texture && c.texture.source) {
                const sx = -c.anchorX * c.width;
                const sy = -c.anchorY * c.height;
                try { ctx.drawImage(c.texture.source, sx, sy, c.width, c.height); } catch (_) {}
            } else if (c instanceof Graphics) {
                for (const cmd of c.commands) {
                    if (cmd.op === 'fill') {
                        ctx.fillStyle = '#' + cmd.color.toString(16).padStart(6, '0');
                        ctx.globalAlpha *= cmd.alpha;
                    }
                    if (cmd.op === 'move') ctx.beginPath(), ctx.moveTo(cmd.x, cmd.y);
                    if (cmd.op === 'line') ctx.lineTo(cmd.x, cmd.y);
                    if (cmd.op === 'close') ctx.closePath();
                    if (cmd.op === 'circle') { ctx.beginPath(); ctx.arc(cmd.x, cmd.y, cmd.r, 0, Math.PI * 2); ctx.closePath(); }
                    if (cmd.op === 'rect') ctx.fillRect(cmd.x, cmd.y, cmd.w, cmd.h);
                    if (cmd.op === 'roundRect') this._roundRect(ctx, cmd.x, cmd.y, cmd.w, cmd.h, cmd.r);
                }
                if (this._lastFill !== false) ctx.fill();
            }
            for (const child of c.children) {
                this._renderContainer(child, ctx, 0, 0);
            }
            ctx.restore();
        }
        _roundRect(ctx, x, y, w, h, r) {
            ctx.beginPath();
            ctx.moveTo(x + r, y);
            ctx.arcTo(x + w, y, x + w, y + h, r);
            ctx.arcTo(x + w, y + h, x, y + h, r);
            ctx.arcTo(x, y + h, x, y, r);
            ctx.arcTo(x, y, x + w, y, r);
            ctx.closePath();
        }
        destroy(removeView) {
            this._destroyed = true;
            if (removeView && this.view.parentNode) this.view.parentNode.removeChild(this.view);
        }
        resize(w, h) {
            this.width = w; this.height = h;
            this.view.width = w; this.view.height = h;
        }
    }

    global.PIXI = {
        Application, Container, Sprite, Graphics, Texture, BaseTexture: Texture,
        VERSION: '7.0.0-lite'
    };
})(window);
